  "plans.eyebrow": "योजना आणि वैशिष्ट्ये",
  "plans.title": "StockHaven योजनांची तुलना करा",
  "plans.intro": "तुम्ही कोणतीही योजना निवडली तरी एकच खाते — Business मध्ये पाच व्यवसायांपर्यंत समाविष्ट आहेत. किमती मासिक, US डॉलरमध्ये आहेत आणि पात्र नवीन वेबसाइट ग्राहकांना Essentials आणि Business मध्ये मिळून एक सात दिवसांची चाचणी मिळू शकते. विद्यमान Essentials सदस्यता Business मध्ये अपग्रेड केल्याने चाचणी पुन्हा सुरू होत नाही किंवा दुसरी मोफत चाचणी तयार होत नाही. वेबसाइट योजनांच्या किमती लागू करांपूर्वीच्या आहेत, असल्यास. सदस्यतेला मंजुरी देण्यापूर्वी तुमचे अचूक शुल्क दाखवले जाईल.",
