  "plans.mobileIncludedNote": "दोन्ही वेबसाइट योजनांमध्ये मोबाइल साथीदार समाविष्ट आहे, त्यामुळे वेबसाइट सदस्याला मासिक मोबाइल शुल्कही वेगळे भरावे लागत नाही.",
  "plans.priceNote": "Essentials $14.99/महिना अधिक लागू कर, असल्यास. Business $29.99/महिना अधिक लागू कर, असल्यास. कोणताही आवश्यक कर प्रदात्याच्या चेकआउटदरम्यान ठरवला जातो आणि पेमेंटपूर्वी अंतिम एकूण रकमेत दिसलाच पाहिजे. हे तुलना पृष्ठ कराचा अंदाज किंवा पेमेंट मंजुरी नाही.",
  "plans.mobilePriceNote": "फक्त-मोबाइल योजना तिच्या नियोजित US मूळ किमतीनुसार $4.99/महिना आहे. App Store किंवा Google Play खरेदीपूर्वी प्रत्यक्ष स्थानिक सदस्यता किंमत आणि लागू कर दाखवतात. तिच्या उत्पादन, साइट आणि कर्मचारी मर्यादा लाँचच्या वेळी, वेबसाइट श्रेणींपासून वेगळ्या, ठरवल्या जातात.",
  "plans.planChangeNote": "वेबसाइट योजना बदलाची पुष्टी बिलिंग प्रदात्याने केलीच पाहिजे. बदलाला मंजुरी देण्यापूर्वी नवीन किंमत, प्रभावी तारीख आणि कोणतीही प्रमाणशीर विभागणी स्पष्ट केली जाईल. अपग्रेडमुळे दुसरी सदस्यता तयार होऊ नये.",
  "plans.providerNote": "किमती, शुल्क आणि चाचण्या तुम्ही ज्या प्रदात्यामार्फत सदस्यता घेता त्याच्याद्वारे हाताळल्या जातात — App Store, Google Play, वेबसाइट किंवा Shopify — या पृष्ठाद्वारे कधीही नाही.",
