  "upgrade.upgradeNeverRestartsTrial": "अपग्रेड केल्याने तुमची मोफत चाचणी कधीही पुन्हा सुरू होत नाही.",
  "upgrade.trialHistoryNote": "तुम्ही Essentials साठी पैसे भरत असाल आणि Business मध्ये गेलात, तर तुम्ही तेच ग्राहक खाते आणि चाचणी इतिहास ठेवता. Business मध्ये अतिरिक्त सात दिवसांची चाचणी समाविष्ट नाही. तुमची मूळ चाचणी अजून सुरू असताना तुम्ही अपग्रेड केल्यास, तिची मूळ समाप्ती तारीख रीसेट होत नाही.",
  "upgrade.providerConfirmNote": "योजना बदलांसाठी बिलिंग प्रदात्याची पुष्टी आवश्यक आहे. बदलाला मंजुरी देण्यापूर्वी कोणताही किमतीतील फरक, प्रमाणशीर विभागणी आणि प्रभावी तारीख दाखवलीच पाहिजे. अपग्रेडमुळे दुसरी एकाच वेळची सदस्यता तयार होऊ नये.",
  "upgrade.chargedThroughProviderNote": "योजना बदलांचे शुल्क बिलिंग प्रदात्यामार्फत आकारले जाते. तुम्ही या पृष्ठावरून तुमच्या सध्याच्या योजनेखालील सदस्यता रद्द करा बटण वापरून किंवा सेटिंग्जमधून तुमची सदस्यता रद्द करू शकता. रद्द केल्याने तुमच्या सशुल्क कालावधीच्या शेवटी भविष्यातील नूतनीकरण थांबते; ते तुमचा प्रवेश एकदम संपवत नाही. विद्यमान मानार्थ कार्यक्षेत्रांवर हे पर्याय पाहिल्याने शुल्क आकारले जात नाही.",
  "billing.cancel.title": "सदस्यता रद्द करा",
  "billing.cancel.description": "{plan} ची सदस्यता रद्द करा. रद्द केल्याने तुमच्या सशुल्क कालावधीच्या शेवटी भविष्यातील नूतनीकरण थांबते — ते तुमचा प्रवेश एकदम कधीही संपवत नाही.",
