  "billing.cancel.refundWindowClosed": "रद्द केल्याने स्वतःहून परतावा दिला जात नाही. परतावा फक्त पहिल्या यशस्वी सशुल्क शुल्काच्या 3 दिवसांच्या आत, {contact} मार्फत विनंती केल्यावरच लागू होतो.",
