  "import.updateDesc": "प्रत्येक पंक्ती SKU किंवा नोंद ID ने जुळवते आणि जुने मूल्य प्रस्तावित नवीन मूल्याशेजारी दाखवते. तुम्ही रिकाम्या जागा साफ करण्यास सांगितले नाही तर रिकामे सेल जतन केलेले मूल्य तसेच ठेवतात आणि प्रमाणांना कधीही स्पर्श केला जात नाही.",
