  "import.excelNote": "Excel कार्यपुस्तिका (.xlsx) थेट वाचल्या जातात — कार्यपत्रक निवडा आणि स्तंभ तुमच्यासाठी जुळवले जातात. कोड संपूर्ण राहतात: मजकूर म्हणून जतन केलेला UPC त्याचे अंक आणि आघाडीचे शून्य ठेवतो. आयात करता न येणाऱ्या पंक्ती कारणासह सूचीबद्ध केल्या जातात",
