  "valuation.footnote": "खर्च मूल्य प्रत्येक उत्पादनाचा सध्याचा एकक खर्च वापरते, त्यामुळे नवीन किमतीने मिळवल्याने संपूर्ण कपाटाचे पुन्हा मूल्यांकन होते. रोखलेली एकके अजूनही येथे मोजली जातात — ती हातात आहेत, फक्त ऑर्डरला वचनबद्ध. गहाळ पैसे कधीही शून्य मानले जात नाहीत; आकडा कळेपर्यंत क्षेत्र रिकामे ठेवा.",
