  "print.pickOrderHint": "दस्तऐवजाचे पूर्वावलोकन करण्यासाठी यादीतून खरेदी ऑर्डर निवडा.",
  "print.pickCustomerOrderHint": "दस्तऐवजाचे पूर्वावलोकन करण्यासाठी यादीतून ग्राहक ऑर्डर निवडा.",
  "print.pickReturnHint": "दस्तऐवजाचे पूर्वावलोकन करण्यासाठी यादीतून नोंदवलेला परतावा निवडा.",
  "print.chooseStyleHint": "शैली निवडा, मग यादीतून उत्पादने निवडा. पूर्वावलोकन प्रिंटरमधून नेमके काय बाहेर येते ते दाखवते.",
  "print.howToReach": "तुमच्या प्रिंटरपर्यंत कसे पोहोचायचे",
  "print.howIntro": "हे अॅप तुमच्याकडे आधीच असलेल्या प्रिंटरशी जोडले जाते — ते स्वतः प्रिंटर नाही. त्यापर्यंत पोहोचण्याचे चार मार्ग आहेत आणि लेबल दोन्ही योजनांवर त्यापैकी कोणत्याही मार्गाने छापली जातात. बांधणी चिठ्ठ्या, खरेदी ऑर्डर, पुरवठादार दस्तऐवज आणि अहवाल फक्त Business आहेत, जोडणी कोणतीही असो.",
  "print.howBluetoothLead": "Bluetooth.",
  "print.howBluetoothBody": "या पृष्ठावरून, डेस्कटॉप Chrome किंवा Edge वर आणि Android Chrome वर: तुमचा लेबल प्रिंटर निवडा आणि लेबल थेट त्याकडे जातात. ते iOS Safari मध्ये चालत नाही — iPhone वर, Bluetooth छपाई त्याऐवजी मोबाइल अॅपसह येते. फक्त Zebra ZPL किंवा Brother ची स्वतःची भाषा बोलणारा प्रिंटर हे पृष्ठ पाठवते ती लेबल समजणार नाही; ते काम करते असे म्हणण्यापूर्वी खऱ्या प्रिंटरविरुद्ध तपासले जाते.",
  "print.howWifiLead": "Wi-Fi.",
  "print.howWifiBody": "प्रिंटर तुमच्या दुकानाच्या Wi-Fi वर स्थापित करा, मग छापा बटण वापरा — ते या संगणकावर स्थापित केलेल्या प्रिंटरमधून, दुकान जाळ्यावर छापते. iPhone वर, AirPrint अंगभूत आहे: त्याच Wi-Fi वरील AirPrint प्रिंटर छपाई पत्रकात आपोआप दिसतो, दोरी नाही आणि अॅप नाही, आणि अॅपला AirPrint-विशिष्ट कोडची गरज नाही. प्रिंटरने AirPrint ला समर्थन दिलेच पाहिजे (बहुतेक नवीन देतात) आणि फोन व प्रिंटर त्याच Wi-Fi वर असलेच पाहिजेत.",
  "print.howEthernetLead": "Ethernet.",
  "print.howEthernetBody": "प्रिंटर Ethernet दोरीने तुमच्या दुकान जाळ्याला जोडा, तो संगणकावर स्थापित करा आणि छापा बटणाने छापा. Ethernet हा डेस्कटॉप आणि संगणक मार्ग आहे — iPhone Ethernet दोऱ्या वापरत नाहीत.",
  "print.howUsbLead": "USB.",
  "print.howUsbBody": "प्रिंटर त्याच्या दोरीने संगणकाला जोडा आणि छापा बटण वापरा — ते तेथे स्थापित केलेल्या प्रिंटरमधून छापते. USB OTG केबल असलेल्या Android फोनवर, वरील USB बटण थेट प्रिंटरशी बोलते. iPhone थेट USB वर छापू शकत नाहीत — तेथे WebUSB नाही — त्यामुळे Wi-Fi / AirPrint वापरा किंवा मोबाइल अॅपमधून Bluetooth वापरा.",
  "print.howCordsLead": "दोऱ्या अजूनही iPhone ला उपयोगी पडतात, एक पायरी दूर.",
  "print.howCordsBody": "दुकान संगणकाला जोडलेला USB प्रिंटर किंवा जाळ्याला जोडलेला Ethernet प्रिंटर तुमच्या iPhone वर दुकान Wi-Fi वर दिसतो (AirPrint / सामायिक प्रिंटर) — दोऱ्या प्रिंटरला जाळ्यावर घट्ट ठेवतात आणि फोन त्याच्यापर्यंत वायरलेस पोहोचतो.",
  "print.howOfflineLead": "इंटरनेट गेल्यास,",
  "print.howOfflineBody": "या पृष्ठावर आधीच असलेली लेबल आणि दस्तऐवज अजूनही छापली जातात — छापा बटण, लेबल PDF, Bluetooth आणि USB यांना जोडणीची गरज नाही. इंटरनेटची गरज आहे ती पृष्ठ आणि त्याची उत्पादने लोड करण्यासाठी. संपूर्ण ऑफलाइन पद्धत (कोणत्याही जोडणीशिवाय अॅपमध्ये काम करणे) ही वेगळी, मोठी बांधणी आहे आणि येथे तिचा दावा केला जात नाही.",
  "print.templatePrice": "किंमत टॅग",
  "print.templatePriceHint": "नाव आणि SKU सह मोठी किंमत",
  "print.templateShelf": "कपाट लेबल",
  "print.templateShelfHint": "नाव, किंमत आणि बारकोड",
  "print.templateBarcode": "बारकोड / SKU",
