  "settings.title": "सेटिंग्ज",
  "settings.trial.cancelKeeps": "तुमच्या चाचणीदरम्यान रद्द केल्याने तुमचे पूर्ण 7 दिवस टिकतात — प्रवेश {date} रोजी संपतो आणि तुमच्याकडून शुल्क आकारले जाणार नाही.",
  "staff.access.noSeatBody": "तुमच्या खात्याला या व्यवसायासाठी कर्मचारी जागा नाही, त्यामुळे त्याचा साठा बंद राहतो. मालकाला तुम्हाला कर्मचारी आणि भूमिका मध्ये जोडण्यास सांगा.",
  "staff.access.noSeatTitle": "हा व्यवसाय तुमच्या लॉगिनसाठी उघडा नाही",
  "staff.access.pendingBody": "या व्यवसायाकडे तुमच्या ईमेलसाठी आमंत्रण आहे जे अजून सक्रिय केलेले नाही. मालकाला तुमची कर्मचारी स्थिती सक्रिय करण्यास सांगा. तोपर्यंत येथे काहीही दिसत नाही.",
  "staff.access.pendingTitle": "तुमचे आमंत्रण अजून सक्रिय नाही",
  "staff.access.signOut": "साइन आउट करा",
  "staff.access.suspendedBody": "प्रशासकाने सक्रिय व्यवसायासाठी हे कर्मचारी खाते निलंबित केले आहे. त्यांना तुम्हाला पुन्हा सक्रिय करण्यास सांगा, मग पुन्हा साइन इन करा.",
  "staff.access.suspendedTitle": "तुमचा प्रवेश विराम दिला आहे",
  "staff.addFirst": "पहिला कर्मचारी सदस्य जोडा",
  "staff.addMember": "कर्मचारी सदस्य जोडा",
  "staff.emptyBody": "व्यक्ती जोडा, त्यांना भूमिका आणि त्यासोबतच्या परवानग्या द्या आणि त्यांना या व्यवसायात साइन इन करण्यासाठी ईमेलने आमंत्रित केले जाते.",
  "staff.emptyTitle": "अजून कर्मचारी नाहीत",
  "staff.eyebrow": "संघ",
  "staff.how.p1": "प्रत्येक सदस्याची भूमिका आणि स्वतःची परवानगी यादी असते, त्यामुळे तुम्ही भूमिकेपासून सुरुवात करू शकता आणि नवीन भूमिका न बनवता एक गोष्ट बदलू शकता. भूमिका संपादित केल्याने तिच्यावर आधीच असलेले सदस्य पुन्हा लिहिले जात नाहीत — त्यांचे भूमिका पूर्वनिर्धारित पुन्हा लागू करण्यासाठी सदस्य उघडा.",
  "staff.how.p2": "सानुकूल भूमिका हे Business वैशिष्ट्य आहे: Essentials पाच अंगभूत भूमिका वापरते (मालक, व्यवस्थापक, साठा लिपिक, विक्री लिपिक, पाहणारा).",
  "staff.how.p3": "आमंत्रणे ईमेलने पाठवली जातात. सदस्य स्वीकारल्यावरच साइन इन करू शकतो आणि एखाद्याला या यादीतून काढल्याने त्याचे अॅप खाते हटवले जात नाही.",
  "staff.how.p4": "दुकान म्हणजे व्यक्तीला नेमलेले ठिकाण. ते त्यांच्या कार्डवर नोंदवले जाते; ते काय उघडू शकतात हे अजूनही त्यांच्या भूमिका आणि परवानग्यांवरून ठरते.",
  "staff.how.p5": "परवानग्या प्रत्येक व्यक्ती काय उघडू शकते ते ठरवतात: त्यांच्या भूमिकेबाहेरील मेनू वस्तू लपवल्या जातात आणि अवरोधित पत्ता पृष्ठाऐवजी “तुमच्या भूमिकेवर नाही” सूचना दाखवतो. बदल त्या व्यक्तीने पुढील वेळी अॅप लोड केल्यावर लागू होतो; सदस्याला निलंबित केल्याने तो पूर्णपणे बाहेर बंद होतो.",
  "staff.how.p6": "प्रशासक सर्व डेटा पाहू आणि बदलू शकतात, अॅप वापरकर्ते आणि भूमिका व्यवस्थापित करू शकतात आणि कर्मचारी भूमिकेने कधीही मर्यादित नसतात. कर्मचारी नोंद नसलेला — नवीन व्यवसायाचा मालक — पूर्ण प्रवेश ठेवतो.",
  "staff.howTitle": "कर्मचारी आणि भूमिका कसे काम करतात",
